-- chair-step: inverse of read_lane_v2_b3_27_workbench_product_capture_payload — un-enrolls workbench.product_capture_payload from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'product_capture_payload' and is_active);
select iam.apply_rls('workbench', 'product_capture_payload', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'product_capture_payload' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'product_capture_payload' and is_active));
